"motor":{a:[{tr:"i. motor",ex:"The new electric motor converts almost all of its energy directly into motion.",exTr:"Yeni elektrik motoru, enerjisinin neredeyse tamamını doğrudan harekete dönüştürüyor."},{tr:"s. motorlu; hareket ettiren",ex:"Motor vehicles account for a large share of urban air pollution.",exTr:"Motorlu taşıtlar, kentsel hava kirliliğinin büyük bir bölümünü oluşturuyor."},{tr:"f. arabayla gitmek",ex:"They motored down the coast road, stopping at every village along the way.",exTr:"Sahil yolundan arabayla ilerlediler, yol boyunca her köyde durdular."}],kl:[{en:"a motor vehicle",tr:"motorlu taşıt"},{en:"the motor industry",tr:"otomotiv sektörü"}]},
