"analyse":{a:[{tr:"f. analiz etmek, incelemek, çözümlemek",ex:"Scientists analysed soil samples from the region to determine the cause of the contamination.",exTr:"Bilim insanları, kirliliğin nedenini belirlemek için bölgeden alınan toprak örneklerini analiz etti."}],kl:[{en:"analyse the data",tr:"verileri çözümlemek"},{en:"analyse the results",tr:"sonuçları incelemek"}]},
"ancestor":{a:[{tr:"i. ata, cet",ex:"Genetic studies revealed that modern humans share a common ancestor with several extinct species.",exTr:"Genetik çalışmalar, modern insanların birkaç nesli tükenmiş türle ortak bir ataya sahip olduğunu ortaya koydu."}],kl:[{en:"a common ancestor",tr:"ortak ata"},{en:"our distant ancestors",tr:"uzak atalarımız"}]},
"brief":{a:[{tr:"f. bilgilendirmek, bilgi vermek",ex:"The officials were briefed about the outbreak before the press conference began.",exTr:"Yetkililer, basın toplantısı başlamadan önce salgın hakkında bilgilendirildi."},{tr:"s. kısa, özlü",ex:"The lawyer gave a brief summary of the case before the judge asked further questions.",exTr:"Avukat, yargıç daha fazla soru sormadan önce davanın kısa bir özetini sundu."}],kl:[{en:"brief sb on sth",tr:"birine bir konuda bilgi vermek"},{en:"in brief",tr:"kısaca"},{en:"a brief period",tr:"kısa bir dönem"}]},
"contract":{a:[{tr:"f. (hastalık) kapmak, yakalanmak",ex:"Workers who handled the chemicals without protection sometimes contract respiratory illnesses over time.",exTr:"Kimyasalları korumasız kullanan işçiler, zamanla bazen solunum yolu hastalıklarına yakalanır."},{tr:"i. sözleşme",ex:"Both companies signed a formal contract outlining the terms of their new business partnership.",exTr:"İki şirket, yeni iş ortaklıklarının şartlarını belirleyen resmi bir sözleşme imzaladı."}],kl:[{en:"contract a disease",tr:"bir hastalığa yakalanmak"},{en:"sign a contract",tr:"sözleşme imzalamak"},{en:"under contract",tr:"sözleşmeli olarak"}]},
