"dose":{a:[{tr:"i. doz",ex:"The pharmacist warned that taking a higher dose than prescribed could cause serious side effects.",exTr:"Eczacı, reçete edilenden daha yüksek bir doz almanın ciddi yan etkilere yol açabileceği konusunda uyardı."},{tr:"f. doz vermek, ilaç vermek",ex:"The nurse dosed the patient carefully to avoid any risk of overdose during treatment.",exTr:"Hemşire, tedavi sırasında aşırı doz riskinden kaçınmak için hastaya dikkatle doz verdi."}],kl:[{en:"a dose of sth",tr:"bir doz bir şey"},{en:"a high dose",tr:"yüksek doz"},{en:"a daily dose",tr:"günlük doz"}]},
"doubt":{a:[{tr:"f. şüphelenmek, şüphe duymak",ex:"Many scientists initially doubted the theory until new evidence confirmed its accuracy.",exTr:"Birçok bilim insanı, yeni kanıtlar doğruluğunu onaylayana kadar teoriden başlangıçta şüphe duydu."},{tr:"i. şüphe",ex:"There is little doubt that regular exercise contributes significantly to better mental health.",exTr:"Düzenli egzersizin daha iyi zihinsel sağlığa önemli ölçüde katkıda bulunduğuna dair çok az şüphe vardır."}],kl:[{en:"have doubts about sth",tr:"bir şeyden şüphe duymak"},{en:"cast doubt on sth",tr:"bir şeyi şüpheli hâle getirmek"},{en:"no doubt",tr:"kuşkusuz"}]},
