"fresh":{a:[{tr:"s. taze",ex:"Nutritionists recommend eating fresh vegetables daily to maintain a balanced and healthy diet.",exTr:"Beslenme uzmanları, dengeli ve sağlıklı bir diyet sürdürmek için her gün taze sebze yemeyi önerir."},{tr:"z. yeni yeni",ex:"The graduate was fresh out of university and eager to start her first job.",exTr:"Mezun, üniversiteden yeni yeni çıkmıştı ve ilk işine başlamak için istekliydi."}],kl:[{en:"fresh air",tr:"temiz hava"},{en:"a fresh start",tr:"yeni bir başlangıç"},{en:"fresh evidence",tr:"yeni kanıt"}]},
"nonetheless":{a:[{tr:"z. yine de, buna rağmen",ex:"The experiment produced unexpected results; nonetheless, researchers considered the study a success.",exTr:"Deney beklenmedik sonuçlar verdi; yine de araştırmacılar çalışmayı başarılı buldu."}]},
"regime":{a:[{tr:"i. (tedavi/beslenme) rejimi, program",ex:"Patients recovering from surgery are usually placed on a strict dietary regime.",exTr:"Ameliyattan iyileşen hastalar genellikle sıkı bir beslenme rejimine tabi tutulur."},{tr:"i. rejim, yönetim (siyasi)",ex:"The new political regime introduced strict censorship laws shortly after taking power.",exTr:"Yeni siyasi rejim, iktidara geldikten kısa süre sonra sıkı sansür yasaları getirdi."}],kl:[{en:"a strict regime",tr:"sıkı bir rejim"},{en:"a training regime",tr:"antrenman programı"},{en:"under the regime",tr:"rejim altında"}]},
