"elements":{a:[{tr:"i. unsurlar, öğeler, elementler",ex:"Chemists identified several rare elements in the mineral samples collected from the volcano.",exTr:"Kimyagerler, yanardağdan toplanan mineral örneklerinde birkaç nadir element tespit etti."}],kl:[{en:"the elements of sth",tr:"bir şeyin unsurları"},{en:"key elements",tr:"temel unsurlar"},{en:"essential elements",tr:"olmazsa olmaz öğeler"}]},
"format":{a:[{tr:"i. biçim, format",ex:"The publisher changed the format of the journal to make articles easier to read online.",exTr:"Yayıncı, makalelerin çevrimiçi okunmasını kolaylaştırmak için derginin biçimini değiştirdi."},{tr:"f. biçimlendirmek",ex:"The technician had to format the hard drive completely before installing the new operating system.",exTr:"Teknisyen, yeni işletim sistemini kurmadan önce sabit diski tamamen biçimlendirmek zorunda kaldı."}],kl:[{en:"in a digital format",tr:"dijital biçimde"},{en:"change the format",tr:"biçimi değiştirmek"}]},
