"reading":{a:[{tr:"i. okuma",ex:"Teachers assigned additional reading to help students prepare for the upcoming history exam.",exTr:"Öğretmenler, öğrencilerin yaklaşan tarih sınavına hazırlanmasına yardımcı olmak için ek okuma ödevi verdi."},{tr:"i. (ölçüm) değer",ex:"The thermometer reading showed a sudden drop in temperature during the overnight storm.",exTr:"Termometre değeri, gece boyunca süren fırtına sırasında sıcaklıkta ani bir düşüş gösterdi."}],kl:[{en:"further reading",tr:"ileri okuma"},{en:"take a reading",tr:"ölçüm almak"},{en:"reading skills",tr:"okuma becerileri"}]},
