"roman":{a:[{tr:"i. dik yazı karakteri (italik olmayan)",ex:"Most academic journals require manuscripts to be typed in roman rather than italic script.",exTr:"Çoğu akademik dergi, makalelerin italik yerine dik yazı karakteriyle yazılmasını şart koşar."},{tr:"s. Roma'ya ait",ex:"Archaeologists uncovered several roman coins buried beneath the ancient city ruins.",exTr:"Arkeologlar, antik şehir kalıntılarının altında gömülü birkaç Roma'ya ait sikke buldu."}],kl:[{en:"roman numerals",tr:"Roma rakamları"},{en:"in roman type",tr:"dik yazı karakteriyle"}]},
"sensible":{a:[{tr:"s. mantıklı, makul, sağduyulu",ex:"It seems sensible for schools to teach basic financial literacy alongside traditional subjects.",exTr:"Okulların geleneksel derslerin yanı sıra temel finansal okuryazarlığı öğretmesi mantıklı görünüyor."}],kl:[{en:"be sensible about sth",tr:"bir konuda makul davranmak"},{en:"a sensible decision",tr:"mantıklı bir karar"},{en:"sensible advice",tr:"makul öğüt"}]},
