"station":{a:[{tr:"f. konuşlandırmak, yerleştirmek",ex:"Soldiers were stationed near the border to monitor movement across the frontier.",exTr:"Sınır boyunca hareketi izlemek için askerler sınıra yakın bir yere konuşlandırıldı."},{tr:"i. istasyon",ex:"Passengers waited patiently at the train station for the delayed express service to arrive.",exTr:"Yolcular, gecikmeli ekspres seferin gelmesini tren istasyonunda sabırla bekledi."}],kl:[{en:"be stationed abroad",tr:"yurt dışında görevlendirilmek"},{en:"a police station",tr:"polis karakolu"},{en:"a railway station",tr:"tren istasyonu"}]},
