"athletic":{a:[{tr:"s. atletik, sportif",ex:"Coaches insist that proper nutrition and consistent sleep contribute as much to athletic performance as demanding physical training does.",exTr:"Antrenörler, uygun beslenmenin ve düzenli uykunun atletik performansa en az zorlu fiziksel antrenman kadar katkı sağladığında ısrar ediyor."}],kl:[{en:"athletic ability",tr:"atletik yetenek"},{en:"an athletic build",tr:"atletik bir vücut yapısı"}]},
