"robot":{a:[{tr:"i. robot",ex:"Hospitals increasingly use a surgical robot to perform delicate operations with greater precision.",exTr:"Hastaneler, hassas ameliyatları daha büyük bir hassasiyetle gerçekleştirmek için giderek daha çok cerrahi robot kullanıyor."}],kl:[{en:"an industrial robot",tr:"endüstriyel robot"},{en:"a robot arm",tr:"robot kol"}]},
"smoke":{a:[{tr:"i. duman",ex:"Thick smoke from the wildfire spread across the valley, forcing thousands of residents to evacuate.",exTr:"Orman yangınından çıkan yoğun duman vadiye yayıldı ve binlerce sakini tahliyeye zorladı."},{tr:"f. sigara içmek",ex:"He used to smoke two packs of cigarettes every single day before finally quitting.",exTr:"Sonunda bırakmadan önce her gün iki paket sigara içerdi."}],kl:[{en:"go up in smoke",tr:"boşa gitmek, suya düşmek"},{en:"smoke a cigarette",tr:"sigara içmek"},{en:"cigarette smoke",tr:"sigara dumanı"}]},
