"running":{a:[{tr:"i. koşu",ex:"Regular running has been shown to reduce the risk of heart disease significantly.",exTr:"Düzenli koşunun, kalp hastalığı riskini önemli ölçüde azalttığı gösterilmiştir."},{tr:"s. sürekli, akan",ex:"The cabin in the mountains had no running water, so residents relied on a nearby well.",exTr:"Dağlardaki kulübede akan su yoktu, bu yüzden sakinler yakındaki bir kuyuya güveniyordu."}],kl:[{en:"running water",tr:"akan su"},{en:"running costs",tr:"işletme maliyetleri"},{en:"go running",tr:"koşuya çıkmak"}]},
