"attend":{a:[{tr:"f. katılmak, devam etmek",ex:"Thousands of scientists traveled abroad to attend the annual conference on climate research.",exTr:"Binlerce bilim insanı, iklim araştırmalarına ilişkin yıllık konferansa katılmak için yurt dışına seyahat etti."},{tr:"f. ilgilenmek",ex:"The nurse attended to the injured passenger until the ambulance finally arrived at the scene.",exTr:"Hemşire, ambulans olay yerine varana kadar yaralı yolcuyla ilgilendi."}],kl:[{en:"attend a meeting",tr:"toplantıya katılmak"},{en:"attend to a matter",tr:"bir işle ilgilenmek"},{en:"attend school",tr:"okula gitmek"}]},
