"capability":{a:[{tr:"i. yetenek, kapasite",ex:"The new satellite has the capability to monitor deforestation across entire continents in real time.",exTr:"Yeni uydu, kıtalar genelindeki ormansızlaşmayı gerçek zamanlı olarak izleme kapasitesine sahiptir."}],kl:[{en:"the capability to do sth",tr:"bir şeyi yapabilme yetisi"},{en:"nuclear capability",tr:"nükleer kapasite"}]},
"infant":{a:[{tr:"i. bebek, süt çocuğu",ex:"Doctors recommend that every infant receive a series of vaccinations during the first year.",exTr:"Doktorlar, her bebeğin ilk yıl içinde bir dizi aşı olmasını önerir."}],kl:[{en:"infant mortality",tr:"bebek ölümleri"},{en:"a newborn infant",tr:"yeni doğmuş bebek"}]},
"learned":{a:[{tr:"s. bilgili, tahsilli",ex:"The museum invited a learned historian to give a lecture on ancient trade routes.",exTr:"Müze, antik ticaret yolları hakkında bir konferans vermesi için bilgili bir tarihçiyi davet etti."},{tr:"s. öğrenilmiş",ex:"Psychologists argue that fear of public speaking is often a learned response rather than an inborn trait.",exTr:"Psikologlar, topluluk önünde konuşma korkusunun genellikle doğuştan gelen bir özellik değil, öğrenilmiş bir tepki olduğunu savunuyor."}],kl:[{en:"learned behaviour",tr:"öğrenilmiş davranış"},{en:"learned helplessness",tr:"öğrenilmiş çaresizlik"}]},
"nowadays":{a:[{tr:"z. bugünlerde, günümüzde",ex:"Nearly every household nowadays relies on the internet for news, banking, and communication.",exTr:"Bugünlerde neredeyse her hane, haber, bankacılık ve iletişim için internete güveniyor."}]},
"plenty":{a:[{tr:"i. bolluk, çokluk",ex:"Nutrition experts insist that children need plenty of fresh fruit and vegetables daily.",exTr:"Beslenme uzmanları, çocukların her gün bol miktarda taze meyve ve sebzeye ihtiyaç duyduğunda ısrar ediyor."},{tr:"z. epey, oldukça",ex:"The new apartment was plenty big enough for a small family of four to live comfortably.",exTr:"Yeni daire, dört kişilik küçük bir ailenin rahatça yaşaması için oldukça genişti."}],kl:[{en:"plenty of time",tr:"bolca zaman"},{en:"plenty of opportunities",tr:"bol fırsat"}]},
