"sharp":{a:[{tr:"s. keskin, sivri, zeki",ex:"Economists reported a sharp decline in consumer spending during the final quarter of the year.",exTr:"Ekonomistler, yılın son çeyreğinde tüketici harcamalarında keskin bir düşüş bildirdi."},{tr:"z. tam (saatinde)",ex:"The train departs at seven o'clock sharp, so passengers should arrive well before then.",exTr:"Tren saat yedide tam olarak kalkar, bu yüzden yolcuların ondan çok önce gelmesi gerekir."}],kl:[{en:"a sharp increase",tr:"keskin bir artış"},{en:"a sharp decline",tr:"sert bir düşüş"},{en:"at nine o'clock sharp",tr:"tam dokuzda"}]},
"sphere":{a:[{tr:"i. alan, çevre",ex:"The professor's research extended far beyond medicine into the sphere of public policy.",exTr:"Profesörün araştırması, tıbbın çok ötesine geçerek kamu politikası alanına uzandı."},{tr:"i. küre",ex:"The children watched in wonder as the glass sphere slowly rotated inside the museum display.",exTr:"Çocuklar, cam kürenin müze vitrininin içinde yavaşça dönüşünü hayretle izledi."}],kl:[{en:"a sphere of influence",tr:"nüfuz alanı"},{en:"the political sphere",tr:"siyasi alan"}]},
"adverse":{a:[{tr:"s. olumsuz, ters, zararlı",ex:"Researchers monitored patients closely to detect any adverse reaction to the experimental drug.",exTr:"Araştırmacılar, deneysel ilaca karşı herhangi bir olumsuz tepkiyi tespit etmek için hastaları yakından izledi."}],kl:[{en:"adverse effects",tr:"olumsuz etkiler"},{en:"adverse weather conditions",tr:"olumsuz hava koşulları"},{en:"an adverse reaction",tr:"ters tepki"}]},
