"diminish":{a:[{tr:"f. azalmak, azaltmak, küçülmek",ex:"Overfishing has caused fish populations in the region to diminish dramatically over the past decade.",exTr:"Aşırı avlanma, bölgedeki balık popülasyonlarının son on yılda büyük ölçüde azalmasına neden oldu."}],es:"decrease, reduce",kl:[{en:"diminish in size",tr:"boyut olarak küçülmek"},{en:"diminishing returns",tr:"azalan getiriler"},{en:"gradually diminish",tr:"giderek azalmak"}]},
