"practise":{a:[{tr:"f. uygulamak, alıştırma yapmak",ex:"Medical students must practise basic procedures repeatedly before working with real patients.",exTr:"Tıp öğrencileri, gerçek hastalarla çalışmadan önce temel işlemleri defalarca uygulamalıdır."},{tr:"f. icra etmek",ex:"She has practised medicine in this small rural town for nearly thirty years without ever moving away.",exTr:"Bu küçük kırsal kasabada neredeyse otuz yıldır hiç taşınmadan hekimlik icra etti."}],kl:[{en:"practise medicine",tr:"hekimlik yapmak"},{en:"practise law",tr:"avukatlık yapmak"},{en:"practise regularly",tr:"düzenli alıştırma yapmak"}]},
"recognise":{a:[{tr:"f. tanımak, fark etmek",ex:"Governments worldwide have begun to recognise climate migration as a serious humanitarian issue.",exTr:"Dünya genelindeki hükümetler, iklim göçünü ciddi bir insani sorun olarak tanımaya başladı."},{tr:"f. resmen kabul etmek, resmen tanımak",ex:"The United Nations officially voted to recognise the newly independent nation later that year.",exTr:"Birleşmiş Milletler, o yılın ilerleyen aylarında yeni bağımsızlığını kazanan ulusu resmen tanıdı."}],kl:[{en:"recognise sb as sth",tr:"birini bir şey olarak tanımak"},{en:"widely recognised as",tr:"yaygın biçimde kabul edilen"},{en:"recognise the importance of",tr:"önemini kabul etmek"}]},
"scope":{a:[{tr:"i. kapsam, alan",ex:"The committee decided to broaden the scope of its investigation into the chemical spill.",exTr:"Komite, kimyasal sızıntıyla ilgili soruşturmasının kapsamını genişletmeye karar verdi."},{tr:"i. olanak",ex:"Managers believe there is still considerable scope for improving efficiency on the factory floor.",exTr:"Yöneticiler, fabrika zemininde verimliliği artırmak için hâlâ önemli bir olanak olduğuna inanıyor."}],kl:[{en:"the scope of sth",tr:"bir şeyin kapsamı"},{en:"beyond the scope of",tr:"kapsamının dışında"},{en:"scope for improvement",tr:"gelişme olanağı"}]},
"significantly":{a:[{tr:"z. önemli ölçüde, hatırı sayılır biçimde",ex:"Air quality improved significantly after the city banned older diesel vehicles from downtown streets.",exTr:"Şehir, eski dizel araçları şehir merkezi sokaklarından yasakladıktan sonra hava kalitesi önemli ölçüde iyileşti."}],kl:[{en:"significantly higher",tr:"önemli ölçüde daha yüksek"},{en:"increase significantly",tr:"önemli ölçüde artmak"},{en:"differ significantly from",tr:"bir şeyden önemli ölçüde farklı olmak"}]},
"younger":{a:[{tr:"s. daha genç, küçük (kardeş vb.)",ex:"Studies show that younger siblings often develop different social skills than their older counterparts.",exTr:"Araştırmalar, küçük kardeşlerin genellikle büyük kardeşlerinden farklı sosyal beceriler geliştirdiğini gösteriyor."}],kl:[{en:"my younger brother",tr:"küçük erkek kardeşim"},{en:"younger than sb",tr:"birinden daha genç"},{en:"the younger generation",tr:"genç kuşak"}]},
