"background":{a:[{tr:"i. arka plan, geçmiş, altyapı",ex:"Employers often check a candidate's background before offering a position of financial responsibility.",exTr:"İşverenler, mali sorumluluk gerektiren bir pozisyon teklif etmeden önce genellikle adayın geçmişini kontrol eder."},{tr:"f. arka planda tutmak, arka planda çalıştırmak",ex:"Administrators decided to background the older files so the new system could run faster.",exTr:"Yöneticiler, yeni sistemin daha hızlı çalışabilmesi için eski dosyaları arka planda tutmaya karar verdi."}],kl:[{en:"in the background",tr:"arka planda"},{en:"family background",tr:"aile geçmişi"},{en:"background information",tr:"arka plan bilgisi"}]},
